c10_math = [
  {"q": "दर्शाइए कि किसी धनात्मक विषम पूर्णांक का वर्ग किसी पूर्णांक m के लिए 8m + 1 के रूप का होता है।", "marks": 3, "ch": "वास्तविक संख्याएं", "subj": "subj-math", "sol": "माना 'a' कोई धनात्मक विषम पूर्णांक है: a = 4q + 1 या 4q + 3। a² = (4q+1)² = 16q² + 8q + 1 = 8(2q²+q) + 1 = 8m + 1। स्थिति 2: a² = (4q+3)² = 16q² + 24q + 9 = 8(2q²+3q+1) + 1 = 8m + 1। अतः वर्ग सदैव 8m + 1 के रूप का होता है।"},
  {"q": "द्विघात बहुपद 6x² - 3 - 7x के शून्यक ज्ञात कीजिए तथा शून्यकों और गुणांकों के बीच संबंध की सत्यता की जांच कीजिए।", "marks": 2, "ch": "बहुपद", "subj": "subj-math", "sol": "6x² - 7x - 3 = (2x - 3)(3x + 1) = 0 => शून्यक α = 3/2, β = -1/3। जांच: α+β = 3/2 - 1/3 = 7/6 = -(-7)/6 = -b/a। αβ = (3/2)(-1/3) = -1/2 = -3/6 = c/a।"},
  {"q": "दो अंकों की एक संख्या एवं उसके अंकों को उलटने पर बनी संख्या का योग 66 है। यदि अंकों का अंतर 2 हो, तो संख्या ज्ञात कीजिए।", "marks": 3, "ch": "दो चर वाले रैखिक समीकरण युग्म", "subj": "subj-math", "sol": "संख्या = 10x + y। उलटने पर = 10y + x। (10x+y)+(10y+x) = 66 => 11(x+y)=66 => x+y=6। x-y=2 हल करने पर x=4, y=2 => संख्या = 42 (या 24)।"},
  {"q": "एक कुटीर उद्योग में प्रत्येक बर्तन की निर्माण लागत उस दिन बने बर्तनों के दुगुने से 3 अधिक थी। यदि कुल लागत रु 90 थी, तो बर्तनों की संख्या ज्ञात कीजिए।", "marks": 4, "ch": "द्विघात समीकरण", "subj": "subj-math", "sol": "लागत = x(2x + 3) = 90 => 2x² + 3x - 90 = 0 => (2x + 15)(x - 6) = 0 => x = 6 बर्तन। प्रत्येक की लागत = 2(6) + 3 = 15 रु।"},
  {"q": "किसी AP के तीसरे और सातवें पदों का योग 6 है और उनका गुणनफल 8 है। प्रथम 16 पदों का योग ज्ञात कीजिए।", "marks": 4, "ch": "समानांतर श्रेणियां", "subj": "subj-math", "sol": "a+2d + a+6d = 6 => a+4d = 3। (a+2d)(a+6d) = 8 => (3-2d)(3+2d) = 8 => 9 - 4d² = 8 => d = ±1/2। d=1/2 पर a=1, S₁₆ = 76; d=-1/2 पर a=5, S₁₆ = 20।"},
  {"q": "बिंदुओं (5, -6) और (-1, -4) को जोड़ने वाले रेखाखंड को y-अक्ष किस अनुपात में विभाजित करता है? प्रतिच्छेद बिंदु भी ज्ञात कीजिए।", "marks": 3, "ch": "निर्देशांक ज्यामिति", "subj": "subj-math", "sol": "y-अक्ष पर बिंदु P(0, y)। 0 = [k(-1) + 5]/(k+1) => k = 5 => अनुपात 5:1। y = [5(-4) + (-6)]/6 = -26/6 = -13/3। बिंदु P(0, -13/3)।"},
  {"q": "सिद्ध कीजिए: (sin θ + cosec θ)² + (cos θ + sec θ)² = 7 + tan² θ + cot² θ।", "marks": 4, "ch": "त्रिकोणमिति का परिचय", "subj": "subj-math", "sol": "LHS = sin²θ + cosec²θ + 2 + cos²θ + sec²θ + 2 = (sin²θ+cos²θ) + 4 + (1+cot²θ) + (1+tan²θ) = 7 + tan²θ + cot²θ = RHS।"},
  {"q": "80 मीटर चौड़ी सड़क के दोनों ओर समान ऊंचाई के खंभे हैं। सड़क के बिंदु से शिखर के उन्नयन कोण 60° और 30° हैं। खंभों की ऊंचाई ज्ञात कीजिए।", "marks": 5, "ch": "त्रिकोणमिति के कुछ अनुप्रयोग", "subj": "subj-math", "sol": "tan 60° = h/x => h = x√3। tan 30° = h/(80-x) => h = (80-x)/√3। x√3 = (80-x)/√3 => 3x = 80 - x => x = 20 मी। h = 20√3 मी (34.64 मी)।"},
  {"q": "सिद्ध कीजिए कि वृत्त के किसी बिंदु पर स्पर्श रेखा स्पर्श बिंदु से जाने वाली त्रिज्या पर लंब होती है।", "marks": 3, "ch": "वृत्त", "subj": "subj-math", "sol": "माना O केंद्र वाले वृत्त की स्पर्श रेखा XY पर बिंदु P है। P के अलावा बिंदु Q बाहर स्थित है, अतः OQ > OP। OP केंद्र से स्पर्श रेखा की न्यूनतम दूरी है, अतः OP ⊥ XY।"},
  {"q": "10 मी व्यास व 2 मी गहरी बेलनाकार टंकी को 20 सेमी व्यास के पाइप द्वारा 3 किमी/घंटा की चाल से बहते पानी से भरने में कितना समय लगेगा?", "marks": 4, "ch": "पृष्ठीय क्षेत्रफल और आयतन", "subj": "subj-math", "sol": "टंकी आयतन = π(5)²(2) = 50π मी³। पाइप आयतन/मिनट = π(0.1)²(50) = 0.5π मी³/मिनट। समय = 50π / 0.5π = 100 मिनट (1 घंटा 40 मिनट)।"},
  {"q": "सिद्ध कीजिए कि 3 + 2√5 एक अपरिमेय संख्या है।", "marks": 2, "ch": "वास्तविक संख्याएं", "subj": "subj-math", "sol": "माना 3 + 2√5 = a/b (सह-अभाज्य पूर्णांक)। 2√5 = a/b - 3 = (a-3b)/b => √5 = (a-3b)/(2b)। RHS परिमेय है किंतु LHS अपरिमेय है, जो विरोधाभास है। अतः यह अपरिमेय संख्या है।"},
  {"q": "एक समकोण त्रिभुज का कर्ण 25 सेमी है तथा शेष दो भुजाओं में 5 सेमी का अंतर है। दोनों भुजाएं ज्ञात कीजिए।", "marks": 3, "ch": "द्विघात समीकरण", "subj": "subj-math", "sol": "भुजाएं x और x + 5। x² + (x+5)² = 25² => 2x² + 10x + 25 = 625 => x² + 5x - 300 = 0 => (x+20)(x-15) = 0 => x = 15 सेमी, दूसरी भुजा = 20 सेमी।"},
  {"q": "उस त्रिभुज का क्षेत्रफल ज्ञात कीजिए जिसके शीर्ष (1, -1), (-4, 6) और (-3, -5) हैं।", "marks": 3, "ch": "निर्देशांक ज्यामिति", "subj": "subj-math", "sol": "क्षेत्रफल = 1/2 | x₁(y₂ - y₃) + x₂(y₃ - y₁) + x₃(y₁ - y₂) | = 1/2 | 1(6 - (-5)) + (-4)(-5 - (-1)) + (-3)(-1 - 6) | = 1/2 | 11 + 16 + 21 | = 48/2 = 24 वर्ग मात्रक।"},
  {"q": "सिद्ध कीजिए: (1 + cot A - cosec A)(1 + tan A + sec A) = 2।", "marks": 3, "ch": "त्रिकोणमिति का परिचय", "subj": "subj-math", "sol": "sin व cos में बदलने पर: [ (sin A + cos A - 1)/sin A ] × [ (cos A + sin A + 1)/cos A ] = [ (sin A + cos A)² - 1 ] / (sin A cos A) = (1 + 2sin A cos A - 1)/(sin A cos A) = 2।"},
  {"q": "सिद्ध कीजिए कि एक वृत्त के परिगत समांतर चतुर्भुज एक समचतुर्भुज (Rhombus) होता है।", "marks": 3, "ch": "वृत्त", "subj": "subj-math", "sol": "हम जानते हैं कि AB + CD = AD + BC। चूंकि समांतर चतुर्भुज में सम्मुख भुजाएं बराबर होती हैं (AB = CD और AD = BC), 2AB = 2AD => AB = AD। अतः चारों भुजाएं बराबर हैं, यह समचतुर्भुज है।"},
  {"q": "एक धातु के गोले की त्रिज्या 4.2 सेमी है। इसे पिघलाकर त्रिज्या 6 सेमी वाले एक बेलन के रूप में ढाला जाता है। बेलन की ऊंचाई ज्ञात कीजिए।", "marks": 3, "ch": "पृष्ठीय क्षेत्रफल और आयतन", "subj": "subj-math", "sol": "गोले का आयतन = 4/3 π r₁³ = 4/3 π (4.2)³। बेलन का आयतन = π r₂² h = π (6)² h। π (36) h = 4/3 π (74.088) => 36 h = 98.784 => h = 2.74 सेमी।"},
  {"q": "एक पासे को एक बार फेंका जाता है। निम्नलिखित को प्राप्त करने की प्रायिकता ज्ञात कीजिए: (i) एक अभाज्य संख्या, (ii) 2 और 6 के बीच स्थित कोई संख्या, (iii) एक विषम संख्या।", "marks": 3, "ch": "प्रायिकता", "subj": "subj-math", "sol": "कुल परिणाम = 6 (1, 2, 3, 4, 5, 6)। (i) अभाज्य संख्याएं (2, 3, 5): P = 3/6 = 1/2। (ii) 2 व 6 के बीच (3, 4, 5): P = 3/6 = 1/2। (iii) विषम संख्याएं (1, 3, 5): P = 3/6 = 1/2।"},
  {"q": "एक मीनार के पाद-बिंदु से एक भवन के शिखर का उन्नयन कोण 30° है और भवन के पाद-बिंदु से मीनार के शिखर का उन्नयन कोण 60° है। यदि मीनार 50 मी ऊंची हो, तो भवन की ऊंचाई ज्ञात कीजिए।", "marks": 4, "ch": "त्रिकोणमिति के कुछ अनुप्रयोग", "subj": "subj-math", "sol": "माना मीनार AB = 50 मी, भवन CD = h मी, दूरी BD = d। ΔABD में: tan 60° = 50/d => d = 50/√3 मी। ΔCDB में: tan 30° = h/d => 1/√3 = h / (50/√3) => h = 50/3 = 16.67 मी।"},
  {"q": "सिद्ध कीजिए कि किसी बाह्य बिंदु से वृत्त पर खींची गई दो स्पर्श रेखाओं की लंबाइयां बराबर होती हैं।", "marks": 5, "ch": "वृत्त", "subj": "subj-math", "sol": "O केंद्र वाले वृत्त पर बाह्य बिंदु P से PA और PB स्पर्श रेखाएं हैं। समकोण ΔOAP और ΔOBP में: ∠OAP = ∠OBP = 90°, OP = OP (उभयनिष्ठ), OA = OB (त्रिज्याएं)। अतः RHS सर्वांगसमता से ΔOAP ≅ ΔOBP => PA = PB (CPCT)।"},
  {"q": "निम्नलिखित बंटन का माध्यक 28.5 है। यदि बारंबारताओं का योग 60 है, तो x और y ज्ञात कीजिए: 0-10 (5), 10-20 (x), 20-30 (20), 30-40 (15), 40-50 (y), 50-60 (5)।", "marks": 5, "ch": "सांख्यिकी", "subj": "subj-math", "sol": "cf: 5, 5+x, 25+x, 40+x, 40+x+y, 45+x+y = 60 => x + y = 15। माध्यक 28.5 है, अतः माध्यक वर्ग 20-30। l = 20, f = 20, cf = 5+x, h = 10, N/2 = 30। 28.5 = 20 + [(30 - (5+x))/20] × 10 => 8.5 = (25-x)/2 => 17 = 25 - x => x = 8। y = 15 - 8 = 7।"}
]

